import{_ as n,P as s,d as o,e as r,x as a,q as i,f as l}from"./chunks/framework.BRr8VP3a.js";const b=JSON.parse('{"title":"Appendix C Common Method Kernel and Cross-Disciplinary Bridging","description":"","frontmatter":{"title":"Appendix C Common Method Kernel and Cross-Disciplinary Bridging","xkChars":2,"xkWords":3956,"xkLessons":{"C.7":{"title":"Sufficient information and correct execution are separate","lead":"A decoder cannot recover a lost distinction; an adequate representation can still be used incorrectly.","explanation":["If q=g∘f, a second conversion h preserves the same final query only when g is constant on the fibers of h restricted to the actual reachable set f(X). Checking every imaginable intermediate value is unnecessary; preserving the distinctions relevant to the final answer on the actual image is essential.","The first conversion can correctly retain a pair of bits while a later sum correctly counts them, yet their composition fails if the final query still asks for the first bit. Changing the final query to the count creates a different successful task rather than repairing the original one.","Actual execution adds another check. If two source states share a representation but need different answers, there is representational insufficiency. If a third representation unambiguously requires one answer but the actual rule returns another, there is also an independent rule error. Fixing the latter does not remove the former."],"distinctions":[{"leftTitle":"Representation insufficiency","leftText":"The retained value merges states requiring different target answers.","rightTitle":"Execution error","rightText":"The actual rule returns a wrong answer despite the relevant retained distinction."}],"teachingExamples":[{"title":"Keeping two bits, then only their sum","text":"The states (0,1) and (1,0) have the same sum but different first bits. The sum answers a counting query but cannot recover the first bit. Keeping that bit separately repairs the specified query.","assumptions":"Finite deterministic bit pairs; final query remains the first bit.","boundary":"No general claim that every compression fails or all details must be retained."}],"boundaries":["A real fault may remain unclassified when its actual input or execution rule is unknown.","Do not erase locally correct outputs because other states fail."],"questionAnswers":[{"question":"If an original document existed somewhere, was the decision maker’s input sufficient?","answer":"Not necessarily. The document must have been accessible in time to the actual actor and rule. Later reconstructability is not timely availability.","basis":"Theory v2, §C.7, with the distinctions explained above."}],"caseLinks":[{"title":"Mars Climate Orbiter: the unit mapping","href":"/en/cases/mars-climate-orbiter"}],"sourceRefs":[{"section":"C.7","startLine":4609,"endLine":4618}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/appendix-c#section-c-7","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§C.7; English reading edition, lines 4609–4618","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"C.9":{"title":"The right extra variable depends on the task","lead":"A mean can preserve total load while losing local overload and position.","explanation":["For two ordered queues with lengths from 0 to 30, the source defines local overload as a maximum above 15. States (0,20) and (10,10) share mean 10 but require opposite overload answers. The mean is correct; its information is insufficient for that target.","Adding the maximum recovers overload and maximum length. With two queues, identical per-position service capacity c, and no new tasks, the smaller queue is 2m−M, so the pair (mean, maximum) also closes under the specified symmetric update.","The result changes with the task and dynamics. Different capacities tied to position make the location of the large queue relevant. With three queues, mean and maximum need not determine the updated total. The finite uniform-state error count is exact for the constructed domain, not an estimate of a real queue population."],"distinctions":[{"leftTitle":"Accurate average","leftText":"Correctly describes the declared mean and, with queue count, total.","rightTitle":"Task sufficiency","rightText":"Retains all distinctions needed for the particular answer or update."}],"teachingExamples":[{"title":"A location-specific service change","text":"With capacities (15,10), states (0,20) and (20,0) share mean 10 and maximum 20. They update to (0,10) and (5,0), so their next mean and maximum differ.","assumptions":"Two ordered queues, no arrivals, each served up to its assigned capacity.","boundary":"The example establishes failure of this representation under this update, not universal failure of aggregation."}],"boundaries":["The 961 equally weighted states are a teaching distribution, not measured frequencies.","Do not attribute a poor decoding rule’s avoidable errors entirely to representation loss."],"questionAnswers":[{"question":"Must every micro-level detail be restored to detect overload?","answer":"No. The maximum suffices for this target. A different target or operation may require a different retained distinction.","basis":"Theory v2, §C.9, with the distinctions explained above."}],"caseLinks":[{"title":"Representation and local overload","href":"/en/concepts/representation"},{"title":"Hurricane Ian: a different target needs different information","href":"/en/cases/representation-hurricane-cone"}],"sourceRefs":[{"section":"C.9","startLine":4631,"endLine":4646}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/appendix-c#section-c-9","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§C.9; English reading edition, lines 4631–4646","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}]},"C.12":{"title":"Three forms of composition need three different checks","lead":"Preserving an answer, composing a causal effect, and executing tasks together are not one “connected” status.","explanation":["Function composition asks whether successive representations preserve the same final query. Causal composition asks whether joint responses and conditions support an effect through the whole chain. Resource composition asks whether the combined tasks satisfy shared constraints. The same workflow can contain all three problems.","The source’s two-task example isolates resources and deadlines. Each task occupies one full slot, both are due in period one, and that period has capacity one. Each is feasible alone; the pair is not. Future capacity cannot repair the original missed deadline unless the deadline is validly changed.","F3 adds an information constraint: one observation may leave several compatible states. A single acceptable action exists precisely when their acceptable-action sets have a nonempty intersection. Each state having some good action is insufficient. Those sets must already include the task’s actual resource, protection, and valid-permission requirements."],"distinctions":[{"leftTitle":"Each state or task has a solution","leftText":"Separate feasible sets are nonempty.","rightTitle":"A common feasible action or plan","rightText":"The relevant intersection or combined constraint set is nonempty."}],"teachingExamples":[{"title":"Opposite actions under the same observation","text":"If one compatible state allows only left and another only right, both are individually solvable but no one action works in both. A valid preservation action allowed in both would make the intersection nonempty.","assumptions":"Finite, single-round, deterministic task and explicitly listed compatible states.","boundary":"Unknown states, sequential strategies, and risk-tolerant decisions require their own analysis."}],"boundaries":["A formal feasibility proof does not certify real resources or permissions.","Legal observation, waiting, or preservation may change the available strategy set, but cannot be assumed costless or automatically available."],"questionAnswers":[{"question":"Can two independently available permissions be combined to authorize an action neither covers?","answer":"No. The mathematical action set cannot manufacture valid authority; permissions must be applicable at the relevant nodes under their governing rules.","basis":"Theory v2, §C.12, with the distinctions explained above."}],"caseLinks":[{"title":"Joint feasibility","href":"/en/concepts/joint-feasibility"},{"title":"Causal chains","href":"/en/concepts/chain"}],"sourceRefs":[{"section":"C.12","startLine":4686,"endLine":4701}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory-v2-en","title":"Xikari: On Conditions, Structure, and Transformation — English reference edition","url":"/en/theory/appendix-c#section-c-12","source_type":"theory_source","version_or_date":"Theory v2, November 2026","locator":"§C.12; English reading edition, lines 4686–4701","claim_support":["The section’s definitions, argument, and conditions, interpreted in this guide."],"limits":["The Chinese original remains authoritative. This is a theory source, not independent empirical support for a real case."]}],"model":"joint"}}},"headers":[],"relativePath":"en/theory/appendix-c.md","filePath":"en/theory/appendix-c.md"}'),c={name:"en/theory/appendix-c.md"};function h(d,e,p,u,m,f){const t=s("SectionLesson");return o(),r("div",null,[e[0]||(e[0]=a("",1)),i(t,{section:"C.7"}),e[1]||(e[1]=a("",1)),i(t,{section:"C.9"}),e[2]||(e[2]=a("",1)),i(t,{section:"C.12"}),e[3]||(e[3]=l("div",{class:"theory-source"},null,-1))])}const g=n(c,[["render",h]]);export{b as __pageData,g as default};
